INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349380, 15000, 'Aaj Tak', 'hi', 'विमल एड केस में शाहरुख, अजय और टाइगर को FDA का नोटिस!', 'https://www.aajtak.in/short-videos/video/sunny-deol-rejects-pan-masala-ads-as-fda-notices-shah-rukh-ajay-tiger-over-vimal-elaichi-mmta-2623405-2026-08-16', 'विमल इलायची के विज्ञापन को लेकर शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को महाराष्ट्र एफडीए ने कारण बताओ नोटिस भेजा है. इसी बीच सनी देओल ने पान मसाला और गुटखा विज्ञापनों से दूरी बनाने के अपने फैसले पर खुलकर बात की. उन्होंने कहा कि वह उन चीजों को प्रमोट नहीं करते, जिन पर उनका भरोसा नहीं है. सनी के बयान ने सेलिब्रिटी विज्ञापन और जिम्मेदारी पर बहस फिर तेज कर दी.', '', '2026-08-16T14:46:24+00:00', '2026-08-16T21:59:49.316460'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
