INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349324, 15011, 'Amar Ujala', 'hi', 'बॉम्बे हाईकोर्ट क्लर्क भर्ती परीक्षा: छात्रों का प्रदर्शन, तकनीकी गड़बड़ी के आरोप; अभिजीत दीपके ने उठाए सवाल', 'https://www.amarujala.com/india-news/bombay-high-court-clerk-typing-test-technical-glitch-student-protest-abhijeet-dipke-raise-questions-2026-08-16', 'बॉम्बे हाईकोर्ट क्लर्क भर्ती परीक्षा: छात्रों का प्रदर्शन, तकनीकी गड़बड़ी के आरोप; अभिजीत दीपके ने उठाए सवाल bombay-high-court-clerk-typing-test-technical-glitch-student-protest-abhijeet-dipke-raise-questions', '', '2026-08-16T03:55:52+00:00', '2026-08-16T21:59:38.594933'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349383, 15011, 'Aaj Tak', 'hi', '''...तो एग्जाम क्यों लेते हैं?'' अभिजीत दिपके ने सरकार को घेरा', 'https://www.aajtak.in/india/maharashtra/story/bombay-high-court-clerk-exam-abhijit-dipke-questions-the-government-ntc-aktw-dskc-2623462-2026-08-16', 'महाराष्ट्र के छत्रपति संभाजीनगर में बॉम्बे हाईकोर्ट क्लर्क भर्ती परीक्षा के दौरान तकनीकी गड़बड़ी हुई. इसमें कंप्यूटर सिस्टम फेल हो गए. कई छात्रों को जबरन फेल घोषित कर दिया गया. कॉकरोच जनता पार्टी के संस्थापक अभिजीत दिपके ने सरकार और परीक्षा व्यवस्था की कड़ी आलोचना की है. उन्होंने परीक्षा दोबारा आयोजित करने की मांग की है.', '', '2026-08-16T16:05:39+00:00', '2026-08-16T21:59:49.626713'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (352975, 15011, 'Patrika', 'hi', 'जब सिस्टम ही नहीं है तो ऑनलाइन परीक्षा क्यों करा रहे ?, अभिजीत दीपके ने क्लर्क भर्ती टेस्ट दोबारा कराने की मांग की | Bombay High Court Clerk Exam Technical Glitch Abhijeet Dipke', 'https://www.patrika.com/national-news/bombay-high-court-clerk-exam-technical-glitch-abhijeet-dipke-20837057', '', 'https://cms.patrika.com/wp-content/uploads/2026/08/Abhijeet-Dipke-2.webp', '20260816', '2026-08-16T23:29:50.758368'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (354320, 15011, 'Dainik Jagran', 'hi', 'बांबे हाई कोर्ट के टाइपिंग टेस्ट में गड़बड़ी का आरोप , सड़कों उतरे लोग ; उम्मीदवारों के प्रदर्शन में दीपके भी हुए शामिल - allegations of irregularities in the bombay high court typing test', 'https://www.jagran.com/news/national-allegations-of-irregularities-in-the-bombay-high-court-typing-test-40342713.html', '', 'https://www.jagranimages.com/images/2026/08/17/template/image/jagran-photo-1786924616324_v.webp', '20260817', '2026-08-17T01:38:38.448427'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (354357, 15011, 'The Hindu', 'en', 'CJP''s Dipke joins protest as candidates claim glitches during online Bombay HC clerk typing test', 'https://www.thehindu.com/news/national/maharashtra/cjps-dipke-joins-protest-as-candidates-claim-glitches-during-online-bombay-hc-clerk-typing-test/article71354704.ece', 'Abhijit Dipke alleged that several candidates were declared failed without their fault and joined the demonstration demanding that the test be conducted afresh', 'https://th-i.thgim.com/public/incoming/ppke9b/article71354716.ece/alternates/LANDSCAPE_1200/PTI08_03_2026_000178B.jpg', '2026-08-17T02:13:17+00:00', '2026-08-17T02:30:44.728700'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (354441, 15011, 'Aaj Tak', 'hi', 'परीक्षा में धांधली पर भड़के CJP संस्थापक अभिजीत दिपके', 'https://www.aajtak.in/short-videos/video/bombay-high-court-clerk-typing-exam-technical-glitches-students-demand-retest-abhijeet-dipke-joins-protest-in-maharashtra-mmta-2623475-2026-08-17', 'महाराष्ट्र के छत्रपति संभाजीनगर में बॉम्बे हाईकोर्ट क्लर्क भर्ती की टाइपिंग परीक्षा के दौरान कंप्यूटर और सर्वर में तकनीकी गड़बड़ियों से छात्रों का गुस्सा फूट पड़ा. कई कंप्यूटरों के माउस और कीबोर्ड काम नहीं कर रहे थे, जबकि कुछ अभ्यर्थियों को कुछ ही मिनटों में सिस्टम से बाहर कर दिया गया. सीजेपी संस्थापक अभिजीत दिपके ने छात्रों के प्रदर्शन में शामिल होकर दोबारा परीक्षा और लिखित आश्वासन की मांग की.', '', '2026-08-17T02:00:03+00:00', '2026-08-17T02:32:01.356984'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
