INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (353831, 15016, 'Aaj Tak', 'hi', 'हमास से डील के लिए ट्रंप ने दामाद को भेजा, मिस्र में पहली मीटिंग', 'https://www.aajtak.in/world/story/donald-trump-son-in-law-jared-kushner-meets-hamas-chief-in-egypt-netanyahu-gaza-ceasefire-talks-ntc-mnrd-smsr-dskc-2623532-2026-08-17', 'गाजा में अटकी सीजफायर डील को आगे बढ़ाने के लिए अमेरिकी राष्ट्रपति डोनाल्ड ट्रंप के दामाद और दूत जेरेड कुशनर ने मिस्र में हमास नेता खलील अल-हय्या से मुलाकात की. 15 सूत्री अमेरिकी रोडमैप में हमास के हथियार छोड़ने और इजरायली सेना की गाजा से वापसी का प्रस्ताव है, लेकिन दोनों पक्षों के बीच अब भी कई मुद्दों पर सहमति नहीं बनी है.', '', '2026-08-17T01:13:12+00:00', '2026-08-17T01:29:39.453956'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
